<?php
require_once __DIR__.'/../app/helpers.php';require_auth();require_once __DIR__.'/../app/Services/NotificationService.php';$svc=new NotificationService(Database::connection());$uid=(int)auth_user()['id'];$events=['transfer_completed','transfer_failed','transfer_pending_approval','transfer_rejected','otp_stage_approved','otp_stage_rejected','bill_payment_completed','card_payment_completed','risk_alert','kyc_status_changed'];$error=null;$success=null;if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();foreach($events as $event){$svc->setPreference($uid,$event,isset($_POST['in_app'][$event]),isset($_POST['email'][$event]),isset($_POST['sms'][$event]));}$success=t('Notification preferences saved.');}catch(Throwable $e){$error=$e->getMessage();}}$existing=[];foreach($svc->preferences($uid) as $p)$existing[$p['event_type']]=$p;$pageTitle=t('Notification Preferences');$currentPage='notifications';require __DIR__.'/partials/header.php';require __DIR__.'/partials/sidebar.php';?><div class="container py-4"><h2 class="mb-4"><?=e(t('Notification Preferences'))?></h2><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><div class="card shadow-sm border-0"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th><?=e(t('Event'))?></th><th><?=e(t('In-app'))?></th><th><?=e(t('Email'))?></th><th><?=e(t('SMS'))?></th></tr></thead><tbody><?php foreach($events as $event):$p=$existing[$event]??['in_app_enabled'=>1,'email_enabled'=>1,'sms_enabled'=>0];?><tr><td><?=e(ucwords(str_replace('_',' ',$event)))?></td><td><input type="checkbox" name="in_app[<?=e($event)?>]" <?=((int)$p['in_app_enabled']?'checked':'')?>></td><td><input type="checkbox" name="email[<?=e($event)?>]" <?=((int)$p['email_enabled']?'checked':'')?>></td><td><input type="checkbox" name="sms[<?=e($event)?>]" <?=((int)$p['sms_enabled']?'checked':'')?>></td></tr><?php endforeach;?></tbody></table></div><div class="card-body"><button class="btn btn-primary"><?=e(t('Save preferences'))?></button> <a href="<?=url('dashboard.php')?>" class="btn btn-link"><?=e(t('Back'))?></a></div></div></form></div><?php require __DIR__.'/partials/footer.php';?>
